#!/usr/bin/env python3

# ----------------------------------------------------------------------
# Usage: python read_csv_csi.py csi_capture_*.csv
# Reads CSV files generated by live_monitor.py --capture-mode complex
#
# Performance notes:
#   - The original per-row loop with df.iloc[idx] was extremely slow for
#     large captures.  The loader now uses vectorized numpy operations
#     which are typically 50-200x faster.
# ----------------------------------------------------------------------

import sys
import numpy as np
import pandas as pd
from pathlib import Path


class CSIDataLoader:
    """Load and parse CSI data from CSV files"""

    def __init__(self, csv_file):
        self.csv_file = csv_file
        self.df = None
        self.csi_data = None
        self.metadata = None
        self.n_subcarriers = 0

    def load(self):
        """Load CSV and extract CSI data."""
        if not Path(self.csv_file).exists():
            raise FileNotFoundError(f"File '{self.csv_file}' not found!")

        print(f"Reading CSV file: {self.csv_file}")
        self.df = pd.read_csv(self.csv_file)
        print(f"CSV shape: {self.df.shape} rows x {self.df.shape[1]} columns")

        self._extract_csi_data()
        self._extract_metadata()

        return self.csi_data, self.metadata

    def _extract_csi_data(self):
        """
        Extract complex CSI data from DataFrame using vectorized numpy.

        Replaces the original row-by-row iloc loop which was the primary
        bottleneck for loading captures with tens of thousands of packets.
        """
        meta_cols = {'ts', 'seq_num', 'core', 'spatial_stream'}
        complex_cols = [c for c in self.df.columns if c not in meta_cols]

        # Determine number of subcarriers and available real/imag columns.
        re_cols = sorted(
            (c for c in complex_cols if c.endswith("_re")),
            key=lambda c: int(c[2:-3]),
        )
        im_cols = sorted(
            (c for c in complex_cols if c.endswith("_im")),
            key=lambda c: int(c[2:-3]),
        )

        n_sc = min(len(re_cols), len(im_cols))
        print(f"Number of subcarriers detected: {n_sc}")

        if n_sc == 0:
            self.csi_data = np.zeros((len(self.df), 0), dtype=np.complex128)
            self.n_subcarriers = 0
            return

        # Bulk-extract all real and imaginary columns as numpy arrays.
        # This is a single pass over the DataFrame instead of one per row.
        re_matrix = self.df[re_cols[:n_sc]].to_numpy(dtype=np.float64)
        im_matrix = self.df[im_cols[:n_sc]].to_numpy(dtype=np.float64)

        self.csi_data = re_matrix + 1j * im_matrix
        self.n_subcarriers = n_sc

    def _extract_metadata(self):
        """Extract metadata from DataFrame."""
        timestamps = self.df['ts'].to_numpy()
        seq_nums = self.df['seq_num'].to_numpy()
        cores = self.df['core'].to_numpy()
        spatial_streams = self.df['spatial_stream'].to_numpy()

        duration = float(timestamps[-1] - timestamps[0])

        self.metadata = {
            'first_ts': float(timestamps[0]),
            'last_ts': float(timestamps[-1]),
            'duration': duration,
            'n_packets': len(self.df),
            'n_subcarriers': self.n_subcarriers,
            'seq_first': int(seq_nums[0]),
            'seq_last': int(seq_nums[-1]),
            'core': (
                int(cores[0])
                if len(np.unique(cores)) == 1
                else np.unique(cores).tolist()
            ),
            'spatial_stream': (
                int(spatial_streams[0])
                if len(np.unique(spatial_streams)) == 1
                else np.unique(spatial_streams).tolist()
            ),
            'rate': (
                len(self.df) / duration
                if duration > 0
                else 0.0
            ),
        }

    def save_filtered_csv(self, filtered_data, output_file=None):
        """Save filtered CSI data back to CSV."""
        if output_file is None:
            output_file = self.csv_file.replace('.csv', '_filtered.csv')

        df_filtered = self.df.copy()

        for sc in range(filtered_data.shape[1]):
            df_filtered[f'sc{sc}_re'] = filtered_data[:, sc].real
            df_filtered[f'sc{sc}_im'] = filtered_data[:, sc].imag

        df_filtered.to_csv(output_file, index=False)
        print(f"Filtered data saved to {output_file}")
        return output_file


def load_csi_from_csv(csv_file):
    """Convenience function to load CSI data."""
    loader = CSIDataLoader(csv_file)
    return loader.load()


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} csi_capture_*.csv")
        print("\nThis script reads CSV files generated by:")
        print("  live_monitor.py --capture-mode complex")
        sys.exit(1)

    try:
        csi_data, metadata = load_csi_from_csv(sys.argv[1])
        print(f"\nSuccessfully loaded {metadata['n_packets']} packets")
        print(f"with {metadata['n_subcarriers']} subcarriers each")
        print(f"Duration: {metadata['duration']:.3f} seconds")
        print(f"Rate: {metadata['rate']:.2f} Hz")
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)